def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that the fixity block is a list
    if not isinstance(fixity, list):
        raise ValueError("Fixity block must be a list")

    # Check that each entry in the fixity block is a dictionary
    for entry in fixity:
        if not isinstance(entry, dict):
            raise ValueError("Fixity block entries must be dictionaries")

    # Check that each dictionary in the fixity block has the required keys
    for entry in fixity:
        if "file" not in entry or "checksum" not in entry:
            raise ValueError("Fixity block entries must have 'file' and 'checksum' keys")

    # Check that the files listed in the fixity block are in the manifest
    for entry in fixity:
        file = entry["file"]
        if file not in manifest_files:
            raise ValueError("File listed in fixity block is not in the manifest")

    # Check that the checksums listed in the fixity block are valid
    for entry in fixity:
        checksum = entry["checksum"]
        if not re.match(r"^[a-z0-9]{32}$", checksum):
            raise ValueError("Checksum listed in fixity block is not valid")

    # Check that the fixity block is not empty
    if len(fixity) == 0:
        raise ValueError("Fixity block must not be empty")

