def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            if arg.op == "&":
                if arg.left == self:
                    new_args.append(arg.right)
                elif arg.right == self:
                    new_args.append(arg.left)
            elif arg.op == "|":
                if arg.left == self:
                    new_args.append(arg.left)
                elif arg.right == self:
                    new_args.append(arg.right)
        else:
            new_args.append(arg)
    return new_args

