def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if verbose:
            print(f"Running command: {command} {args}")

        try:
            process = subprocess.run(command, args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed with exit code {e.returncode}")
            if not hide_stderr:
                print(e.stderr.decode("utf-8"))
            return e.returncode

        if process.returncode != 0:
            if verbose:
                print(f"Command failed with exit code {process.returncode}")
            if not hide_stderr:
                print(process.stderr.decode("utf-8"))
            return process.returncode

        if verbose:
            print(process.stdout.decode("utf-8"))

    return 0

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the hierarchy
    for obj in self.objects:
        num_objects += 1

        # Check if the object is valid
        if validate_objects:
            if obj.is_valid():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj.id} is not valid")

        # Check if the object's digest is correct
        if check_digests:
            if obj.digest != obj.calculate_digest():
                if show_warnings:
                    print(f"Object {obj.id} has an incorrect digest")

    return num_objects, good_objects

