              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if os.name == 'nt':
            platform = 0
        else:
            platform = 1

    if platform == 1:
        return re.split(r'(\s+)', s)
    else:
        return re.split(r'(\s+)', s)

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.

    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not filename:
        filename = os.path.basename(archive_path)
    tmp_dir = tempfile.mkdtemp(dir=tmp_path)
    subprocess.run(["tar", "-xvf", archive_path, "-C", tmp_dir])
    return "file://" + os.path.join(tmp_dir, filename)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency format")

    if unit == "minute":
        return datetime.timedelta(minutes=number)
    elif unit == "hour":
        return datetime.timedelta(hours=number)
    elif unit == "day":
        return datetime.timedelta(days=number)
    elif unit == "week":
        return datetime.timedelta(weeks=number)
    elif unit == "month":
        return datetime.timedelta(weeks=number * 4)
    elif unit == "year":
        return datetime.timedelta(weeks=number * 52)
    else:
        raise ValueError("Invalid frequency unit")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name = matcher.group(1)
    default = matcher.group(2)
    value = os.environ.get(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise ValueError(f"Environment variable {name} is not defined")
    else:
        return value

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if not cwd:
        cwd = os.getcwd()
    if not env:
        env = os.environ
    if verbose:
        print("Running command:", " ".join(commands), "with args:", args, "in directory:", cwd)
    try:
        process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate(args)
        if not hide_stderr:
            print(error.decode("utf-8"))
        return output.decode("utf-8")
    except Exception as e:
        print("Error running command:", " ".join(commands), "with args:", args, "in directory:", cwd)
        print("Error:", e)
        return None

