def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")

    if protocol_version is None:
        # Return all available versions
        return {(3, 5): Bolt35Handler, (3, 4): Bolt34Handler, (3, 3): Bolt33Handler, (3, 2): Bolt32Handler, (3, 1): Bolt31Handler, (3, 0): Bolt30Handler}
    else:
        # Return a single version
        if protocol_version in [(3, 5), (3, 4), (3, 3), (3, 2), (3, 1), (3, 0)]:
            return {protocol_version: Bolt35Handler if protocol_version == (3, 5) else Bolt34Handler if protocol_version == (3, 4) else Bolt33Handler if protocol_version == (3, 3) else Bolt32Handler if protocol_version == (3, 2) else Bolt31Handler if protocol_version == (3, 1) else Bolt30Handler}
        else:
            return {}

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, bytes):
        return (seq, bytes)
    elif isinstance(seq, bytearray):
        return (seq, bytearray)
    elif isinstance(seq, memoryview):
        return (seq, memoryview)
    elif isinstance(seq, array.array):
        return (seq, array.array)
    elif isinstance(seq, collections.abc.Sequence):
        return (seq, type(seq))
    else:
        raise TypeError("Expected a sequence type, but got " + str(type(seq)))

    if bufsize is not None:
        if not isinstance(bufsize, int):
            raise TypeError("Expected an integer for bufsize, but got " + str(type(bufsize)))
        if bufsize < 0:
            raise ValueError("bufsize must be non-negative")

    return (seq, type(seq))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Parameters:
        iface (type): The interface to verify
        candidate (type): The candidate class to verify
        tentative (bool, optional): Whether to perform a tentative verification or not

    Returns:
        bool: Whether the candidate class can provide the interface
    """

    if not isinstance(iface, type):
        raise ValueError("iface must be a class")

    if not isinstance(candidate, type):
        raise ValueError("candidate must be a class")

    if iface is candidate:
        return True

    if not tentative:
        if not issubclass(candidate, iface):
            return False

    for base in candidate.__bases__:
        if verifyClass(iface, base, tentative):
            return True

    for attr in candidate.__dict__.values():
        if isinstance(attr, property):
            if verifyClass(iface, attr.fget, tentative):
                return True

    return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    Args:
        bases (tuple): A tuple of base classes
        explicit_mc (type, optional): An explicit metaclass to use. Defaults to None.

    Returns:
        type: The determined metaclass
    """
    if explicit_mc is not None:
        return explicit_mc
    if len(bases) == 1:
        return bases[0].__class__
    if len(bases) > 1:
        metaclasses = [base.__class__ for base in bases]
        if len(set(metaclasses)) == 1:
            return metaclasses[0]
        else:
            raise TypeError("Can't determine metaclass from multiple bases")
    return type

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def _create_in_regex(self) -> Pattern:
