            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from bs4 import BeautifulSoup

    # Retrieve the webfinger document
    response = requests.get(handle)
    if response.status_code != 200:
        raise Exception("Unable to retrieve webfinger document")

    # Parse the document
    soup = BeautifulSoup(response.text, "html.parser")
    data = {}
    for link in soup.find_all("link"):
        if link.get("rel") == "diaspora:profile":
            data["profile"] = link.get("href")
        elif link.get("rel") == "diaspora:pod":
            data["pod"] = link.get("href")
        elif link.get("rel") == "diaspora:aspects":
            data["aspects"] = link.get("href")
        elif link.get("rel") == "diaspora:contacts":
            data["contacts"] = link.get("href")
        elif link.get("rel") == "diaspora:publickey":
            data["public_key"] = link.get("href")
        elif link.get("rel") == "diaspora:privatekey":
            data["private_key"] = link.get("href")

    return data

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/host-meta.xrds")
        response.raise_for_status()
        xrd = XRD.from_xml(response.content)
        return xrd
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 404:
            raise DiasporaHostNotFoundError(f"Host {host} not found")
        else:
            raise DiasporaHostError(f"Error retrieving host-meta from {host}: {e}")
    except requests.exceptions.RequestException as e:
        raise DiasporaHostError(f"Error retrieving host-meta from {host}: {e}")

