def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    # Load YAML file
    with open(yaml_file, 'r') as f:
        data = yaml.safe_load(f)

    # Validate that all mandatory fields are present
    for field in cls.MANDATORY_FIELDS:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in YAML file '{yaml_file}'")

    # Validate that all fields have the correct type
    for field, field_type in cls.FIELD_TYPES.items():
        if field not in data:
            continue
        if not isinstance(data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in YAML file '{yaml_file}' has incorrect type. Expected {field_type}, got {type(data[field])}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Arguments:
        parser_dict (dict): A dictionary containing the parsed spec file.
    """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif key == "include":
            self._include_groups(value)

